import React, { useEffect, useState } from "react";
import api from "@/lib/api";
import PageHeader from "@/components/PageHeader";
import StatusBadge from "@/components/StatusBadge";
import {
  LayoutDashboard, Monitor, CheckCircle2, Truck, Wrench, AlertTriangle,
  UserX, DollarSign, ShieldAlert, KeyRound, CalendarClock, Ticket, TrendingUp, Activity,
} from "lucide-react";
import {
  PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis,
  Tooltip, CartesianGrid,
} from "recharts";

const COLORS = ["#CC0000", "#1D4ED8", "#047857", "#D97706", "#6D28D9", "#0891B2", "#DB2777", "#65A30D"];

function Kpi({ icon: Icon, label, value, sub, accent = "text-slate-400", testid }) {
  return (
    <div className="kpi-card rounded-lg border border-border bg-white p-4" data-testid={testid}>
      <div className="flex items-start justify-between">
        <div>
          <div className="text-[13px] font-medium text-muted-foreground">{label}</div>
          <div className="mt-1 text-3xl font-black tabular text-foreground">{value}</div>
          {sub && <div className="mt-0.5 text-xs text-muted-foreground">{sub}</div>}
        </div>
        <Icon className={`h-6 w-6 ${accent}`} />
      </div>
    </div>
  );
}

export default function Dashboard() {
  const [s, setS] = useState(null);
  const [charts, setCharts] = useState(null);
  const [activity, setActivity] = useState([]);
  const [alerts, setAlerts] = useState({ warranties: [], licenses: [] });

  useEffect(() => {
    api.get("/dashboard/summary").then((r) => setS(r.data)).catch(() => {});
    api.get("/dashboard/charts").then((r) => setCharts(r.data)).catch(() => {});
    api.get("/dashboard/recent-activity").then((r) => setActivity(r.data.items)).catch(() => {});
    api.get("/dashboard/alerts").then((r) => setAlerts(r.data)).catch(() => {});
  }, []);

  const money = (v) => `RD$ ${Number(v || 0).toLocaleString("es-DO", { minimumFractionDigits: 0 })}`;

  return (
    <div>
      <PageHeader title="Panel Ejecutivo" subtitle="Indicadores clave del inventario tecnológico" icon={LayoutDashboard} />

      {/* Primary KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-5 gap-4 mb-4">
        <Kpi icon={Monitor} label="Total de Activos" value={s?.total_assets ?? "—"} accent="text-primary" testid="kpi-total" />
        <Kpi icon={CheckCircle2} label="Disponibles" value={s?.disponibles ?? "—"} accent="text-emerald-500" testid="kpi-available" />
        <Kpi icon={Truck} label="Asignados" value={s?.asignados ?? "—"} sub={`Utilización ${s?.utilizacion ?? 0}%`} accent="text-blue-500" testid="kpi-assigned" />
        <Kpi icon={Wrench} label="En Mantenimiento" value={s?.mantenimiento ?? "—"} accent="text-amber-500" testid="kpi-maintenance" />
        <Kpi icon={AlertTriangle} label="Dañados" value={s?.danados ?? "—"} accent="text-red-500" testid="kpi-damaged" />
      </div>

      {/* Secondary KPIs */}
      <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-4 mb-6">
        <Kpi icon={DollarSign} label="Valor Inventario" value={money(s?.valor_inventario)} accent="text-emerald-600" testid="kpi-value" />
        <Kpi icon={UserX} label="Sin Responsable" value={s?.sin_responsable ?? "—"} accent="text-slate-500" testid="kpi-unassigned" />
        <Kpi icon={ShieldAlert} label="Garantías x Vencer" value={s?.garantias_por_vencer ?? "—"} sub="Próx. 60 días" accent="text-amber-600" testid="kpi-warranties" />
        <Kpi icon={KeyRound} label="Licencias x Expirar" value={s?.licencias_por_expirar ?? "—"} sub="Próx. 60 días" accent="text-violet-600" testid="kpi-licenses" />
        <Kpi icon={CalendarClock} label="Mant. Programados" value={s?.mantenimientos_programados ?? "—"} accent="text-cyan-600" testid="kpi-scheduled" />
        <Kpi icon={Ticket} label="Tickets Abiertos" value={s?.tickets_abiertos ?? "—"} accent="text-primary" testid="kpi-tickets" />
      </div>

      {/* Charts + Activity */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 rounded-lg border border-border bg-white p-5">
          <h3 className="font-bold mb-4 flex items-center gap-2"><TrendingUp className="h-4 w-4 text-primary" /> Activos por Categoría</h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={charts?.by_category || []} margin={{ left: -20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#eef1f5" vertical={false} />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={-20} textAnchor="end" height={60} />
              <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
              <Tooltip contentStyle={{ borderRadius: 8, border: "1px solid #e2e8f0" }} />
              <Bar dataKey="value" radius={[4, 4, 0, 0]} fill="#CC0000" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="rounded-lg border border-border bg-white p-5">
          <h3 className="font-bold mb-4">Estado del Inventario</h3>
          <ResponsiveContainer width="100%" height={280}>
            <PieChart>
              <Pie data={charts?.by_status || []} dataKey="value" nameKey="name" cx="50%" cy="45%" outerRadius={90} label={(e) => e.value}>
                {(charts?.by_status || []).map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
              </Pie>
              <Tooltip contentStyle={{ borderRadius: 8, border: "1px solid #e2e8f0" }} />
            </PieChart>
          </ResponsiveContainer>
          <div className="flex flex-wrap gap-2 justify-center mt-2">
            {(charts?.by_status || []).map((d, i) => (
              <span key={i} className="flex items-center gap-1.5 text-xs">
                <span className="h-2.5 w-2.5 rounded-full" style={{ background: COLORS[i % COLORS.length] }} />{d.name}
              </span>
            ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-6">
        {/* Activity */}
        <div className="lg:col-span-2 rounded-lg border border-border bg-white p-5">
          <h3 className="font-bold mb-4 flex items-center gap-2"><Activity className="h-4 w-4 text-primary" /> Actividad Reciente</h3>
          {activity.length === 0 ? (
            <div className="py-10 text-center text-muted-foreground text-sm">No hay actividad aún</div>
          ) : (
            <div className="space-y-1">
              {activity.map((a) => (
                <div key={a.id} className="flex items-center gap-3 py-2 border-b border-border last:border-0 text-sm">
                  <span className="h-2 w-2 rounded-full bg-primary shrink-0" />
                  <span className="flex-1">{a.description || a.action}</span>
                  <span className="text-xs text-muted-foreground">{a.user_name}</span>
                  <span className="text-xs text-muted-foreground tabular">{new Date(a.timestamp).toLocaleString("es-DO", { dateStyle: "short", timeStyle: "short" })}</span>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Alerts */}
        <div className="rounded-lg border border-border bg-white p-5">
          <h3 className="font-bold mb-4 flex items-center gap-2"><ShieldAlert className="h-4 w-4 text-amber-500" /> Alertas</h3>
          <div className="space-y-3">
            <div className="text-xs font-semibold uppercase text-muted-foreground">Garantías por vencer</div>
            {alerts.warranties.length === 0 ? <p className="text-sm text-muted-foreground">Ninguna</p> :
              alerts.warranties.slice(0, 5).map((w, i) => (
                <div key={i} className="flex justify-between text-sm">
                  <span className="truncate">{w.asset_tag} · {w.name}</span>
                  <span className="text-amber-600 tabular">{new Date(w.warranty_end).toLocaleDateString("es-DO")}</span>
                </div>
              ))}
            <div className="text-xs font-semibold uppercase text-muted-foreground pt-2">Licencias por expirar</div>
            {alerts.licenses.length === 0 ? <p className="text-sm text-muted-foreground">Ninguna</p> :
              alerts.licenses.slice(0, 5).map((l, i) => (
                <div key={i} className="flex justify-between text-sm">
                  <span className="truncate">{l.software_name}</span>
                  <span className="text-violet-600 tabular">{new Date(l.expiry_date).toLocaleDateString("es-DO")}</span>
                </div>
              ))}
          </div>
        </div>
      </div>
    </div>
  );
}
